draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;
var half = W / 2;

function cross(cx, cy, s) {
  ctx.strokeStyle = C.faint;
  ctx.beginPath();
  ctx.moveTo(cx - s, cy - s); ctx.lineTo(cx + s, cy + s);
  ctx.moveTo(cx + s, cy - s); ctx.lineTo(cx - s, cy + s);
  ctx.stroke();
}

function arrow(x1, y1, x2, y2, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1), h = 8;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - h * Math.cos(a - 0.42), y2 - h * Math.sin(a - 0.42));
  ctx.lineTo(x2 - h * Math.cos(a + 0.42), y2 - h * Math.sin(a + 0.42));
  ctx.closePath(); ctx.fill();
}

function panel(x0, sign, label) {
  var i, j;
  for (i = 0; i < 5; i++) {
    for (j = 0; j < 3; j++) {
      cross(x0 + half * 0.16 + i * half * 0.17, H * 0.26 + j * H * 0.21, 4);
    }
  }
  var cx = x0 + half * 0.42, cy = H * 0.52;
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(cx, cy, 6, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = C.paper;
  ctx.fillText(sign > 0 ? "+" : "-", cx - 3, cy + 4);

  arrow(cx, cy, cx + half * 0.30, cy, C.figure);
  ctx.fillStyle = C.ink;
  ctx.fillText("v", cx + half * 0.31, cy + 15);

  var fy = sign > 0 ? -1 : 1;
  arrow(cx, cy, cx, cy + fy * H * 0.26, C.accent);
  ctx.fillStyle = C.ink;
  ctx.fillText("F = qvB", cx + 8, cy + fy * H * 0.26 + (sign > 0 ? -4 : 14));
  ctx.fillText(label, x0 + half * 0.10, H - 8);
}

panel(0, 1, "positive charge: force is up");
panel(half, -1, "negative charge: force is down");

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(half, 22); ctx.lineTo(half, H - 22); ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("B points into the page everywhere (the x marks)", 10, 15);

out.note = "Point fingers along v, curl them into B, thumb gives v x B. For a negative charge the force is the other way.";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var e = 1.6e-19, mp = 1.67e-27;
var m = p.mass * mp;
var v = p.speed * 1e6;
var B = p.field;
var r = m * v / (e * B);
var T = 2 * Math.PI * m / (e * B);
var f = 1 / T;

var S = (0.40 * H) / 0.10;
var rp = r * S;
var x0 = W * 0.14, y0 = H * 0.52;
var cx = x0, cy = y0 + rp;

ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
var i, j;
for (i = 0; i < 9; i++) {
  for (j = 0; j < 5; j++) {
    var dx = W * 0.06 + i * W * 0.11, dy = H * 0.10 + j * H * 0.20;
    ctx.beginPath(); ctx.arc(dx, dy, 1.6, 0, Math.PI * 2); ctx.stroke();
  }
}

ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 5]);
ctx.lineWidth = 1;
ctx.beginPath();
ctx.arc(cx, cy, rp, 0, Math.PI * 2);
ctx.stroke();
ctx.setLineDash([]);

var Tvis = T * 3e6;
var ph = (t / Tvis) * 2 * Math.PI;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
var k;
for (k = 0; k <= 60; k++) {
  var a = -Math.PI / 2 + (ph % (2 * Math.PI)) * k / 60;
  var px = cx + rp * Math.cos(a), py = cy + rp * Math.sin(a);
  if (k === 0) { ctx.moveTo(px, py); } else { ctx.lineTo(px, py); }
}
ctx.stroke();

var ang = -Math.PI / 2 + ph;
var bx = cx + rp * Math.cos(ang), by = cy + rp * Math.sin(ang);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(bx, by, 5, 0, Math.PI * 2); ctx.fill();

ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(bx, by); ctx.lineTo(cx, cy); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("F points at the centre", cx + 8, cy - 6);

var bar = 0.05 * S;
ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(W - 20 - bar, H - 16); ctx.lineTo(W - 20, H - 16); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.lineWidth = 1;
ctx.fillText("5 cm", W - 20 - bar, H - 22);
ctx.fillText("B out of the page", 10, 14);

out.note = "r = " + r.toFixed(4) + " m,  T = " + T.toExponential(3) + " s,  f = " + (f / 1e6).toFixed(2) + " MHz  (change the speed: T does not move)";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var I = p.current, B = p.field, L = p.sep, m = p.mass / 1000;
var F = I * L * B;
var a = F / m;

function arrow(x1, y1, x2, y2, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 1.8;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var an = Math.atan2(y2 - y1, x2 - x1), h = 8;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - h * Math.cos(an - 0.42), y2 - h * Math.sin(an - 0.42));
  ctx.lineTo(x2 - h * Math.cos(an + 0.42), y2 - h * Math.sin(an + 0.42));
  ctx.closePath(); ctx.fill();
}

var yTop = H * 0.28, yBot = H * 0.78;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(W * 0.08, yTop); ctx.lineTo(W * 0.94, yTop);
ctx.moveTo(W * 0.08, yBot); ctx.lineTo(W * 0.94, yBot);
ctx.moveTo(W * 0.08, yTop); ctx.lineTo(W * 0.08, yBot);
ctx.stroke();

ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
var i, j;
for (i = 0; i < 8; i++) {
  for (j = 0; j < 2; j++) {
    var dx = W * 0.18 + i * W * 0.095, dy = yTop + (j + 1) * (yBot - yTop) / 3;
    ctx.beginPath();
    ctx.moveTo(dx - 3.5, dy - 3.5); ctx.lineTo(dx + 3.5, dy + 3.5);
    ctx.moveTo(dx + 3.5, dy - 3.5); ctx.lineTo(dx - 3.5, dy + 3.5);
    ctx.stroke();
  }
}

var span = W * 0.70;
var tt = t % 2.2;
var s = 0.5 * a * tt * tt * 0.004;
if (s > 1) { s = 1; }
var xr = W * 0.16 + s * span * 0.9;

ctx.strokeStyle = C.accent;
ctx.lineWidth = 5;
ctx.beginPath(); ctx.moveTo(xr, yTop); ctx.lineTo(xr, yBot); ctx.stroke();

arrow(xr, yBot - 6, xr, yTop + 10, C.figure);
ctx.fillStyle = C.ink;
ctx.fillText("I", xr - 12, (yTop + yBot) / 2);

arrow(xr, H * 0.15, xr + Math.min(W * 0.22, 30 + F * 60), H * 0.15, C.accent);
ctx.fillStyle = C.ink;
ctx.fillText("F = I L B", xr + 10, H * 0.12);
ctx.fillText("B into the page", W * 0.08, 14);
ctx.fillText("rails", W * 0.08, yBot + 16);

out.note = "F = " + F.toFixed(3) + " N,  a = " + a.toFixed(1) + " m/s^2  (reverse nothing: flip I or B and the rod runs the other way)";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var th = p.angle * Math.PI / 180;
var N = p.turns, I = p.current, A = p.area, B = p.field;
var mu = N * I * A;
var tau = mu * B * Math.sin(th);
var U = -mu * B * Math.cos(th);

function arrow(x1, y1, x2, y2, col, lw) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = lw;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var an = Math.atan2(y2 - y1, x2 - x1), h = 8;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - h * Math.cos(an - 0.42), y2 - h * Math.sin(an - 0.42));
  ctx.lineTo(x2 - h * Math.cos(an + 0.42), y2 - h * Math.sin(an + 0.42));
  ctx.closePath(); ctx.fill();
}

var cx = W * 0.46, cy = H * 0.52;
var R = Math.min(W * 0.20, H * 0.30);

ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
var i;
for (i = 0; i < 5; i++) {
  var y = H * 0.12 + i * H * 0.19;
  ctx.beginPath(); ctx.moveTo(W * 0.06, y); ctx.lineTo(W * 0.94, y); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W * 0.94, y); ctx.lineTo(W * 0.94 - 6, y - 3.5); ctx.lineTo(W * 0.94 - 6, y + 3.5);
  ctx.closePath(); ctx.fillStyle = C.faint; ctx.fill();
}
ctx.fillStyle = C.ink;
ctx.fillText("B", W * 0.90, H * 0.06);

var ex = R * Math.sin(th), ey = -R * Math.cos(th);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 4;
ctx.beginPath();
ctx.moveTo(cx - ex, cy - ey); ctx.lineTo(cx + ex, cy + ey);
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cx + ex, cy + ey, 6, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(cx - ex, cy - ey, 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText(".", cx + ex - 1, cy + ey - 1);
ctx.fillStyle = C.ink;
ctx.fillText("loop seen edge on", cx - R - 10, H - 10);

arrow(cx, cy, cx + R * 1.15 * Math.cos(th - Math.PI / 2), cy + R * 1.15 * Math.sin(th - Math.PI / 2), C.figure, 2);
ctx.fillStyle = C.ink;
ctx.fillText("normal, m", cx + R * 1.25 * Math.cos(th - Math.PI / 2) + 4, cy + R * 1.25 * Math.sin(th - Math.PI / 2));

var fl = 22 + 120 * tau;
if (fl > H * 0.22) { fl = H * 0.22; }
arrow(cx + ex, cy + ey, cx + ex, cy + ey - fl, C.figure, 1.6);
arrow(cx - ex, cy - ey, cx - ex, cy - ey + fl, C.figure, 1.6);
ctx.fillStyle = C.ink;
ctx.fillText("force couple", cx + ex + 8, cy + ey - fl - 4);

ctx.fillText("angle between m and B: " + p.angle.toFixed(0) + " deg", 8, 14);

out.note = "m = " + mu.toFixed(3) + " A m^2,  torque = " + tau.toFixed(4) + " N m,  U = " + U.toFixed(4) + " J";
